// Split into parts based on whitespace
var parts = text.Split(
    new[] { ' ' }, 
    StringSplitOptions.RemoveEmptyEntries
);

// Adjust this according to the actual format of your PDF lines
return new {
    Item = parts.Length > 0 ? parts[0] : "",
    Code = parts.Length > 1 ? parts[1] : "",
    Qty = parts.Length > 2 ? parts[2] : "",
    UnitPrice = parts.Length > 3 ? parts[3] : "",
    LineTotal = parts.Length > 4 ? parts[4] : ""
};
